import {makeDailyPlan,tasks,radiationRules} from './crew.mjs';
const dailyNode=(tag,text,cls)=>{const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(cls)el.className=cls;return el;};
export class DailyMedicalUI{
 constructor(mission,book,onChange,onExecute){
  this.$=id=>document.getElementById(id);this.onChange=onChange;this.onExecute=onExecute;this.requests=[];
  this.$('medical-day').addEventListener('change',()=>{this.plan=null;this.requestsDirty=false;this.render();});this.$('medical-member').addEventListener('change',()=>this.render());this.$('history-range').addEventListener('change',()=>this.renderHistory());
  this.$('capture-exam').addEventListener('click',()=>this.capture());
  this.$('daily-exam-form').addEventListener('submit',e=>{e.preventDefault();this.save();});
  for(const id of ['exam-hr','exam-oxygen','exam-radiation','exam-fatigue','exam-dose','exam-notes','exam-trusted','exam-severe'])this.$(id).addEventListener('input',()=>{this.source='manual';});
  this.$('generate-day-plan').addEventListener('click',()=>{try{const requests=this.requests.map(row=>({hour:Number(row.hour.value),taskId:row.task.value}));this.requestsDirty=false;this.plan=makeDailyPlan(this.mission.monitor.members,this.book,this.day(),requests);this.$('plan-feedback').textContent='План рассчитан. Проверьте участников и причины отложенных заданий.';this.renderPlan();}catch(error){this.$('plan-feedback').textContent=error.message;}});
  this.$('save-day-plan').addEventListener('click',()=>{try{if(!this.plan||this.plan.day!==this.day())throw Error('Сначала рассчитайте план для выбранного дня.');this.book.savePlan(this.day(),this.plan);this.$('plan-feedback').textContent=this.book.persistent?'План сохранён в браузере.':this.book.warning;this.status();}catch(error){this.$('plan-feedback').textContent=error.message;}});
  this.$('export-medical').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(this.book.export(),null,2)],{type:'application/json'})),a=dailyNode('a');a.href=url;a.download='alpha-daily-medical.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
  this.$('import-medical').addEventListener('change',async()=>{try{const file=this.$('import-medical').files?.[0];if(!file)return;if(file.size>5000000)throw Error('Архив слишком большой (максимум 5 МБ).');this.book.import(JSON.parse(await file.text()));this.mission.syncDailyExams();this.render();this.onChange();this.$('exam-feedback').textContent='Архив загружен без перезаписи существующих осмотров.';}catch(error){this.$('exam-feedback').textContent=error.message;}});
  window.addEventListener('resize',()=>this.renderHistory());this.setContext(mission,book);
 }
 setContext(mission,book){this.mission=mission;this.book=book;this.plan=null;this.$('medical-day').value=book.today();this.$('medical-day').max=book.today();this.$('history-range').value='7';this.$('medical-member').replaceChildren();for(const m of mission.monitor.members){const option=dailyNode('option',m.name);option.value=m.id;this.$('medical-member').append(option);}this.$('medical-member').value=mission.monitor.members[0].id;this.createRequests();this.render();}
 day(){return this.$('medical-day').value;}
 member(){return this.mission.monitor.members.find(m=>m.id===this.$('medical-member').value)||this.mission.monitor.members[0];}
 status(){const today=this.book.today(),missing=this.mission.monitor.members.filter(m=>!this.book.get(today,m.id));this.$('daily-coverage').textContent=(4-missing.length)+'/4 · '+today;this.$('daily-gate').textContent=missing.length?'Миссия ожидает ежедневный медосмотр: '+missing.map(m=>m.name).join(', ')+'. Осмотр нужен каждому участнику один раз за сегодняшний день.':'Все четыре осмотра за сегодня записаны. Назначение зависит от результатов и текущей телеметрии.';this.$('daily-gate').classList.toggle('blocked',!!missing.length);this.$('storage-warning').textContent=this.book.warning;this.$('medical-day').max=today;}
 fill(data){for(const [id,value]of Object.entries({'exam-hr':data.values.heart_rate,'exam-oxygen':data.values.spO2,'exam-radiation':data.values.radiation_level,'exam-fatigue':Number(data.fatigue.toFixed(1)),'exam-dose':Math.ceil(data.dose*1000000)/1000000}))this.$(id).value=value;this.$('exam-notes').value=data.notes||data.symptoms.map(s=>s.text).join('. ');this.$('exam-trusted').checked=data.trusted;this.$('exam-severe').checked=data.symptoms.some(s=>s.severe);}
 capture(){if(this.day()!==this.book.today()){this.$('exam-feedback').textContent='Снимок текущей симуляции можно записать только за сегодня. Архивные результаты вводятся вручную.';return;}if(this.book.get(this.day(),this.member().id))return;this.fill(this.member());this.source='simulation';this.$('exam-feedback').textContent='Подставлены текущие синтетические измерения. Нажмите «Записать медосмотр» для фиксации.';}
 save(){try{const number=id=>{const text=String(this.$(id).value).trim();if(!text)throw Error('Заполните все числовые показатели.');return Number(text);};const notes=this.$('exam-notes').value.trim(),severe=this.$('exam-severe').checked;
  this.book.record(this.day(),this.member(),{values:{heart_rate:number('exam-hr'),spO2:number('exam-oxygen'),radiation_level:number('exam-radiation')},fatigue:number('exam-fatigue'),dose:number('exam-dose'),trusted:this.$('exam-trusted').checked,symptoms:notes||severe?[{text:notes||'Выраженная жалоба',severe}]:[],notes,source:this.source||'manual'});
  this.mission.syncDailyExams();this.plan=null;this.requestsDirty=false;this.render();this.onChange();this.$('exam-feedback').textContent='Осмотр записан. Повторная запись за эту дату заблокирована. '+(this.book.warning||'');
 }catch(error){this.$('exam-feedback').textContent=error.message;}}
 render(){this.status();const exam=this.book.get(this.day(),this.member().id),locked=!!exam;
 this.$('exam-status').textContent=locked?'ОСМОТР ЗАПИСАН':'ОСМОТР НЕ ПРОЙДЕН';
 for(const id of ['exam-hr','exam-oxygen','exam-radiation','exam-fatigue','exam-dose','exam-notes','exam-trusted','exam-severe','save-exam','capture-exam'])this.$(id).disabled=locked;
 this.$('capture-exam').disabled=locked||this.day()!==this.book.today();
 this.fill(exam||this.member());this.source=exam?.source||(this.day()===this.book.today()?'simulation':'manual');if(!exam&&this.day()!==this.book.today()){for(const id of ['exam-hr','exam-oxygen','exam-radiation','exam-fatigue','exam-dose','exam-notes'])this.$(id).value='';}this.$('exam-feedback').textContent=locked?`Записано ${exam.recordedAt||''}. Источник: ${exam.source==='simulation'?'симуляция':'ручной ввод'}.`:'Проверьте значения и запишите осмотр. До записи назначения блокируются.';
 this.renderHistory();this.renderPlan();}
 renderHistory(){const member=this.member(),comparison=this.book.comparison(this.day(),member.id);this.$('daily-comparison-title').textContent=member.name+' / сравнение осмотров';const box=this.$('daily-comparison');box.replaceChildren();
 if(comparison.current&&!comparison.current.trusted||comparison.previous&&!comparison.previous.trusted)box.append(dailyNode('p','В сравнении есть недостоверные измерения: они не подтверждают допуск.','bad-value'));
 if(!comparison.current)box.append(dailyNode('p','За выбранный день осмотр не записан.','warning-value'));
 else if(!comparison.previous)box.append(dailyNode('p','Первый сохранённый осмотр. Для сравнения нужен ещё один день.'));
 else{box.append(dailyNode('p',`${this.day()} ↔ ${comparison.previous.day}. Сравнение с предыдущим доступным осмотром, не обязательно с предыдущим календарным днём.`));for(const [key,label,unit]of [['heart_rate','Пульс','уд/мин'],['spO2','Кислород','п.п.'],['radiation_level','Фон','мкЗв/ч'],['fatigue','Усталость','п.п.'],['dose','Доза','мкЗв']]){const delta=comparison.delta[key];box.append(dailyNode('span',`${label}: ${delta>0?'+':''}${delta} ${unit}`,'daily-delta'));}}
 let history=this.book.history(member.id).filter(e=>e.day<=this.day());const count=this.$('history-range').value;if(count!=='all')history=history.slice(-Number(count||7));this.$('history-empty').textContent=history.length?`${history.length} сохранённых осмотров. Пропущенные дни не заменяются вымышленными данными. Красные столбцы — недостоверные измерения.`:'История пуста. Запишите осмотр; диаграммы появятся после сохранения. Для сравнения добавьте результаты за другой день.';
 const body=this.$('daily-history-body');body.replaceChildren();for(const e of [...history].reverse()){const row=dailyNode('tr');for(const text of [e.day,e.values.heart_rate,e.values.spO2,e.values.radiation_level,e.fatigue,e.dose.toFixed(4),(e.source==='simulation'?'симуляция':'вручную')+' / '+(e.trusted?'достоверно':'недостоверно')])row.append(dailyNode('td',text));body.append(row);}
 for(const [id,key]of [['daily-hr-chart','heart_rate'],['daily-oxygen-chart','spO2'],['daily-radiation-chart','radiation_level'],['daily-fatigue-chart','fatigue'],['daily-dose-chart','dose']])this.drawDiagram(this.$(id),history,key);
 }
 drawDiagram(canvas,history,key){const rect=canvas.getBoundingClientRect();if(!rect.width)return;const ctx=canvas.getContext('2d');if(!ctx)return;const dpr=window.devicePixelRatio||1,w=rect.width,h=150;canvas.width=w*dpr;canvas.height=h*dpr;ctx.scale(dpr,dpr);ctx.clearRect(0,0,w,h);ctx.font='9px monospace';ctx.fillStyle='#8fa6b4';if(!history.length){ctx.fillText('Нет сохранённых осмотров',12,60);return;}const values=history.map(e=>e.values[key]??e[key]),max=(Math.max(...values)>0?Math.max(...values):1)*1.2,barWidth=(w-42)/history.length;
 ctx.strokeStyle='#2b3e4b';for(let i=0;i<4;i++){const y=110-i*30;ctx.beginPath();ctx.moveTo(32,y);ctx.lineTo(w,y);ctx.stroke();ctx.fillStyle='#8fa6b4';ctx.fillText((max*i/3).toFixed(max<1?3:0),0,y+3);}
 history.forEach((e,i)=>{const height=values[i]/max*90,x=34+i*barWidth;ctx.fillStyle=e.trusted?'#61e2d3':'#ff576c';ctx.fillRect(x+barWidth*.15,110-height,barWidth*.7,height);ctx.fillStyle='#c8dce5';if(history.length<=7)ctx.fillText(values[i].toFixed(key==='dose'?4:key==='radiation_level'?2:1),x,104-height);if(history.length<=7||i===0||i===history.length-1){ctx.save();ctx.translate(x+3,123);ctx.rotate(-.3);ctx.fillStyle='#8fa6b4';ctx.fillText(e.day.slice(5),0,0);ctx.restore();}});
 }
 createRequests(){const root=this.$('daily-plan-requests');root.replaceChildren();this.requests=[];for(const [i,taskId]of ['repair','research','eva','evacuation'].entries()){const row=dailyNode('div',undefined,'daily-request'),label=dailyNode('label','ЧАС'),hour=dailyNode('input');hour.type='number';hour.min='0';hour.max='23';hour.step='1';hour.value=[9,11,14,16][i];hour.setAttribute('aria-label','Час задания '+(i+1));label.append(hour);const select=dailyNode('select');select.setAttribute('aria-label','Задание '+(i+1));for(const [id,t]of Object.entries(tasks)){const option=dailyNode('option',t.name);option.value=id;select.append(option);}select.value=taskId;row.append(label,select);root.append(row);this.requests.push({hour,task:select});for(const el of [hour,select])el.addEventListener('input',()=>{this.plan=null;this.requestsDirty=true;this.$('daily-plan-results').replaceChildren(dailyNode('p','Параметры изменены — пересчитайте дневной план.','warning-value'));this.$('save-day-plan').disabled=true;this.$('plan-feedback').textContent='Задания изменены — пересчитайте план перед сохранением.';});}}
 renderPlan(){this.$('plan-date').textContent=this.day();const plan=this.plan||(!this.requestsDirty?this.book.plans[this.day()]:null);const root=this.$('daily-plan-results');root.replaceChildren();this.$('save-day-plan').disabled=!this.plan;if(!plan){root.append(dailyNode('p','План за этот день ещё не составлен.','small muted'));return;}
 for(const row of plan.rows||[]){const card=dailyNode('article',undefined,'daily-plan-row');const name=id=>this.mission.monitor.members.find(m=>m.id===id)?.name||id;card.append(dailyNode('h3',`${String(row.hour).padStart(2,'0')}:00 / ${tasks[row.taskId]?.name||row.taskId}`),dailyNode('p',row.status==='planned'?`Группа: ${row.ids.map(name).join(', ')}. Резерв: ${name(row.reserveId)}.`:'Задание отложено: подходящая группа не найдена.',row.status==='planned'?'':'bad-value'),dailyNode('p',row.reason,'small muted'));
 const details=dailyNode('details'),summary=dailyNode('summary','Почему назначены эти участники');details.append(summary);for(const c of row.comparison||[])details.append(dailyNode('p',`${c.name}: ${c.eligible?c.score+'/100':c.reasons.join('; ')}`));card.append(details);
 const execute=dailyNode('button','Подготовить выполнение','secondary');execute.disabled=row.status!=='planned'||this.day()!==this.book.today()||this.mission.finished;execute.addEventListener('click',()=>{this.$('plan-feedback').textContent=this.onExecute(row,this.day());});card.append(execute);root.append(card);}
 }
}
